"use strict";
import { CurrencyAmount } from "@uniswap/sdk-core";
import { popupRegistry } from "components/Popups/registry";
import { useAccount } from "hooks/useAccount";
import { ApprovalState, useApproveCallback } from "hooks/useApproveCallback";
import { useState } from "react";
import styled from "styled-components";
import { Flex, Text, useSporeColors, SpinningLoader } from "ui/src";
import { getContractAddress } from "uniswap/src/constants/contracts";
import { ABX_ABSTRACT_TESTNET } from "uniswap/src/constants/tokens";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useIncentivizeContext } from "../ContextProvider";
export default function EditAmoutAndAllowButton() {
  const { setIncentivizeStep, termsAccepted } = useIncentivizeContext();
  const colors = useSporeColors();
  const account = useAccount();
  const [isApproving, setIsApproving] = useState(false);
  const voterAddress = getContractAddress(account.chainId || UniverseChainId.Sepolia, "Voter");
  const approvalAmount = CurrencyAmount.fromRawAmount(ABX_ABSTRACT_TESTNET, "1000000000000000000000");
  const [approvalState, approveCallback] = useApproveCallback(approvalAmount, voterAddress);
  const handleApprove = async () => {
    if (!approveCallback) return;
    try {
      setIsApproving(true);
      await approveCallback();
      setIncentivizeStep("step-1");
    } catch (error) {
      console.error("Approval failed:", error);
      popupRegistry.addPopup(
        {
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Approval Failed",
            description: `Failed to approve ABX token: ${error.message}`,
            action: "approve"
          }
        },
        `incentive-approve-error-${Date.now()}`
      );
    } finally {
      setIsApproving(false);
    }
  };
  const Button = styled.button`
    all: unset;
    padding: 16px 10px;
    background-color: ${(props) => props.$disabled ? colors.surface2.val : props.$lock ? colors.surface2Hovered.val : colors.accent1.val};
    color: ${(props) => props.$disabled ? colors.neutral3.val : props.$lock ? colors.neutral1.val : colors.surface1.val};
    border-radius: 12px;
    cursor: ${(props) => props.$disabled ? "not-allowed" : "pointer"};
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 8px;
    flex: 1;
    transition: all 0.2s ease;
    &:hover {
      opacity: ${(props) => props.$disabled ? 1 : 0.7};
    }
  `;
  const isApprovalNeeded = approvalState === ApprovalState.NOT_APPROVED;
  const isApprovalPending = approvalState === ApprovalState.PENDING || isApproving;
  const isAllowButtonDisabled = !termsAccepted || !isApprovalNeeded || isApprovalPending || !account.address;
  return <Flex mt={"$spacing24"} row gap={"$gap12"} alignItems="center">
      <Button role="button" $lock onClick={() => setIncentivizeStep("step-2")}>
        <Text variant="buttonLabel3" color={"inherit"}>
          Edit amount
        </Text>
      </Button>
      <Button role="button" onClick={handleApprove} $disabled={isAllowButtonDisabled}>
        {isApprovalPending && <SpinningLoader size={16} />}
        <Text variant="buttonLabel3" color={"inherit"}>
          {!termsAccepted ? "Accept Terms" : isApprovalPending ? "Approving" : approvalState === ApprovalState.APPROVED ? "Approved" : "Allow"}
        </Text>
      </Button>
    </Flex>;
}
