"use strict";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { useVoterReads } from "./useVoterContract";
import { useAvailableGauges } from "./useGaugeData";
import { getAbstractSubgraphs, getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { formatEther } from "viem";
import { usePublicClient } from "wagmi";
async function fetchPoolVotingDataFromChain(publicClient, poolAddress, chainId) {
  try {
    const contracts = getAbstractContracts(chainId);
    if (!contracts?.voter) {
      console.log("Voter contract not available for chain", chainId);
      return null;
    }
    const KNOWN_GAUGE_ADDRESS = "0xfadc4ba8d14015105ec62430def4f0a8abe6bf7e";
    if (poolAddress.toLowerCase() !== "0x1fc67ac780874a6fccd9968857973207e76fe390") {
      console.log("Pool not recognized for direct chain calls:", poolAddress);
      return null;
    }
    const GAUGE_ABI = [
      {
        inputs: [],
        name: "totalWeight",
        outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
        stateMutability: "view",
        type: "function"
      },
      {
        inputs: [],
        name: "emissions",
        outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
        stateMutability: "view",
        type: "function"
      }
    ];
    const gaugeData = await publicClient.readContract({
      address: KNOWN_GAUGE_ADDRESS,
      abi: GAUGE_ABI,
      functionName: "totalWeight"
    });
    const totalVotes = parseFloat(formatEther(gaugeData));
    return {
      poolAddress,
      totalVotes: totalVotes.toFixed(2),
      poolId: KNOWN_GAUGE_ADDRESS
    };
  } catch (error) {
    console.error("Failed to fetch pool voting data from chain:", error);
    return null;
  }
}
async function fetchPoolVotingData(subgraphUrl, poolAddress) {
  const POOL_VOTES_QUERY = `
    query GetPoolVotes($poolAddress: String!) {
      gauges(where: { pool: $poolAddress }) {
        id
        pool
        totalWeight
        emissions
        poolType
      }
      
      votes(
        where: { gauge_: { pool: $poolAddress } }
        first: 1000
      ) {
        id
        weight
        tokenId
        gauge {
          id
          pool
        }
      }
    }
  `;
  try {
    const response = await fetch(subgraphUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query: POOL_VOTES_QUERY,
        variables: { poolAddress: poolAddress.toLowerCase() }
      })
    });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }
    const data = await response.json();
    if (data.errors) {
      console.error("GraphQL errors:", data.errors);
      throw new Error(`GraphQL errors: ${JSON.stringify(data.errors)}`);
    }
    const gauges = data.data?.gauges || [];
    const votes = data.data?.votes || [];
    if (gauges.length > 0) {
      const gauge = gauges[0];
      const totalVotesFromVotes = votes.reduce((sum, vote) => {
        const voteWeight = parseFloat(formatEther(BigInt(vote.weight || "0")));
        return sum + voteWeight;
      }, 0);
      const gaugeTotalWeight = parseFloat(formatEther(BigInt(gauge.totalWeight || "0")));
      const totalVotes = Math.max(gaugeTotalWeight, totalVotesFromVotes);
      return {
        poolAddress,
        totalVotes: totalVotes.toFixed(2),
        poolId: gauge.id
      };
    }
    return null;
  } catch (error) {
    console.error("Failed to fetch pool voting data:", error);
    return null;
  }
}
