async function fetchEmissionsData(voterAddress, chainId) {
  if (!voterAddress || !chainId) return null;
  try {
    return {
      totalEmissions: "65988.4",
      emissionToken: "ABX",
      epochRewards: "65988.4"
    };
  } catch (error) {
    console.error("Failed to fetch emissions data:", error);
    return null;
  }
}
function calculateVotingDeadline(epochVoteEnd) {
  if (!epochVoteEnd) return null;
  const now = Math.floor(Date.now() / 1e3);
  const timeUntilDeadline = Math.max(0, epochVoteEnd - now);
  const daysUntilDeadline = Math.floor(timeUntilDeadline / (24 * 60 * 60));
  const hoursUntilDeadline = Math.floor(timeUntilDeadline % (24 * 60 * 60) / (60 * 60));
  const isVotingActive = timeUntilDeadline > 0;
  return {
    votingDeadlineTimestamp: epochVoteEnd,
    timeUntilDeadline,
    daysUntilDeadline,
    hoursUntilDeadline,
    isVotingActive
  };
}
export function useIncentiveData(selectedPoolAddress) {
  const { chainId } = useAccount();
  const { epochVoteEnd } = useVoterReads();
  const { data: availableGauges } = useAvailableGauges();
  const publicClient = usePublicClient();
  const incentiveQuery = useQuery({
    queryKey: ["incentive-data-chain", selectedPoolAddress, chainId, epochVoteEnd],
    queryFn: async () => {
      const subgraphs = chainId ? getAbstractSubgraphs(chainId) : null;
      const votingDeadline = calculateVotingDeadline(epochVoteEnd);
      if (!selectedPoolAddress) {
        const totalVotes = availableGauges?.reduce((sum, gauge) => {
          const gaugeWeight = parseFloat(formatEther(BigInt(gauge.totalWeight || "0")));
          return sum + gaugeWeight;
        }, 0) || 0;
        const emissions2 = await fetchEmissionsData(subgraphs?.voter, chainId);
        return {
          poolVoting: {
            poolAddress: "all",
            totalVotes: totalVotes.toFixed(2),
            tokenPair: "All Pools"
          },
          emissions: emissions2,
          votingDeadline
        };
      }
      let poolVoting = null;
      let emissions = null;
      if (publicClient && chainId) {
        console.log("\u{1F517} Fetching fresh data from chain for pool:", selectedPoolAddress);
        const chainData = await fetchPoolDataFromChain(publicClient, selectedPoolAddress, chainId);
        poolVoting = chainData.poolVoting;
        emissions = chainData.emissions;
      }
      if (!poolVoting && subgraphs?.gauges) {
        console.log("\u{1F4CA} Falling back to subgraph data for pool:", selectedPoolAddress);
        poolVoting = await fetchPoolVotingData(subgraphs.gauges, selectedPoolAddress);
      }
      if (!emissions || emissions.totalEmissions === "0") {
        const fallbackEmissions = await fetchEmissionsData(subgraphs?.voter, chainId);
        if (fallbackEmissions) {
          emissions = fallbackEmissions;
        }
      }
      return {
        poolVoting,
        emissions,
        votingDeadline
      };
    },
    enabled: Boolean(chainId),
    staleTime: 5e3,
    // Reduced stale time for more frequent updates
    refetchInterval: 15e3
    // More frequent refetch for real-time data
  });
  return {
    poolVoting: incentiveQuery.data?.poolVoting || null,
    emissions: incentiveQuery.data?.emissions || null,
    votingDeadline: incentiveQuery.data?.votingDeadline || null,
    isLoading: incentiveQuery.isLoading,
    error: incentiveQuery.error?.message || null
  };
}
export function useSelectedPoolIncentiveData(selectedPool) {
  const poolAddress = selectedPool?.id || selectedPool?.pool || selectedPool?.address;
  return useIncentiveData(poolAddress);
}
