"use strict";
import CurrencySearchModal from "components/SearchModal/CurrencySearchModal";
import { useEffect, useState } from "react";
import { Flex, Separator, Text, useSporeColors } from "ui/src";
import { useEnabledChains } from "uniswap/src/features/chains/hooks/useEnabledChains";
import { useIncentivizeContext } from "../ContextProvider";
import { CurrencySelector } from "./CurrencySelector";
import PoolCheckOptions from "./PoolCheckOptions";
import StepOnePools from "./StepOnePools";
export default function IncentivizePoolFirstStep() {
  const [selectedInputToken, setSelectedInputToken] = useState("");
  const [isOpenCurrencyModal, setIsOpenCurrencyModal] = useState(false);
  const { token0, setToken0, token1, setToken1 } = useIncentivizeContext();
  const { chains } = useEnabledChains();
  const colors = useSporeColors();
  const handleCurrencySelect = (currency) => {
    setIsOpenCurrencyModal(false);
    if (selectedInputToken === "token0") {
      setToken0(currency);
    } else {
      setToken1(currency);
    }
  };
  const handleCurrentyModal = (token) => {
    setSelectedInputToken(token);
    setIsOpenCurrencyModal(true);
  };
  useEffect(() => {
    if (token0 === token1) {
      selectedInputToken === "token0" ? setToken1("") : setToken0("");
    }
  }, [token0, token1]);
  const tokens = [
    { title: "Token you want to incentivise", token: token0 },
    { title: "Token you want to pair with", token: token1 }
  ];
  return <Flex>
      <Flex
    p={"$spacing24"}
    $md={{ p: "$spacing16" }}
    borderRadius={"$rounded12"}
    maxWidth={700}
    width={"100%"}
    style={{
      background: `linear-gradient(180deg, ${colors.surface2.variable} 0%, transparent 100%)`
    }}
  >
        <Text variant="subheading1">Incentivise Pool</Text>

        <Separator my={"$spacing24"} $md={{ my: "$spacing24" }} width={"100%"} borderColor={"$surface3"} height={1} />
        <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "1fr 1fr" }}
    gap={"$gap24"}
    $lg={{ gridTemplateColumns: "1fr" }}
  >
          {tokens.map((item, index) => <Flex flexDirection="column" gap={"$gap12"}>
              <Text variant="body2" fontWeight="$bold" color={"$neutral2"}>
                {item.title}
              </Text>
              <CurrencySelector
    emphasis={item.token ? void 0 : "primary"}
    currencyInfo={item.token}
    onPress={() => handleCurrentyModal("token" + index)}
  />
            </Flex>)}
        </Flex>
        <Separator my={"$spacing36"} $md={{ my: "$spacing24" }} width={"100%"} borderColor={"$surface3"} height={1} />
        <PoolCheckOptions />

        <CurrencySearchModal
    isOpen={isOpenCurrencyModal}
    onDismiss={() => setIsOpenCurrencyModal(false)}
    onCurrencySelect={handleCurrencySelect}
    chainIds={chains}
    excludeNativeTokens={true}
  />
      </Flex>

      <StepOnePools />
    </Flex>;
}
